import{_ as n,C as i,c as l,o as h,a3 as s,G as a,j as r,a as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Process a request","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/requests/process-request.md","filePath":"master/supply-chain/maintenance/requests/process-request.md","lastUpdated":1791902625000}'),c={name:"master/supply-chain/maintenance/requests/process-request.md"};function g(u,e,p,d,m,q){const t=i("ImagePopup");return h(),l("div",null,[e[0]||(e[0]=s('<h1 id="process-a-request" tabindex="-1">Process a request <a class="header-anchor" href="#process-a-request" aria-label="Permalink to &quot;Process a request&quot;">​</a></h1><p>Processing a request means moving it through its stages until the work is finished. You also keep notes, send messages and plan follow-up tasks on the same page. Everything about one job stays in one place.</p><blockquote><p><strong>In simple words:</strong> Click the next stage when the work moves on. Use the chat panel to talk about the job.</p></blockquote><p>Open <code>Maintenance → Maintenance Requests</code> and click the request, for example <strong>Hydraulic press oil leak</strong>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>Create the request first. See <a href="./create-request.html">Create a maintenance request</a>.</p></div><h2 id="move-a-request-through-the-stages" tabindex="-1">Move a request through the stages <a class="header-anchor" href="#move-a-request-through-the-stages" aria-label="Permalink to &quot;Move a request through the stages&quot;">​</a></h2><p>The request page has two tabs at the top: <strong>View</strong> and <strong>Edit</strong>. The <strong>View</strong> tab shows the stage bar but is read only. Use the <strong>Edit</strong> tab to change the stage.</p><ol><li>Open the <strong>Edit</strong> tab of <strong>Hydraulic press oil leak</strong>.</li><li>Click <strong>In Progress</strong> in the stage bar. The stage does not save by itself. Click <strong>Save changes</strong>. The notification <strong>Maintenance request updated</strong> appears with the text &quot;The maintenance request has been updated successfully.&quot; You stay on the <strong>Edit</strong> page with the new stage highlighted.</li></ol>',8)),a(t,{src:"/images1/maintenance/req_process_in_progress.png",alt:"Edit page of Hydraulic press oil leak with In Progress highlighted in the stage bar"}),e[1]||(e[1]=r("ol",{start:"3"},[r("li",null,[o("When the work is done, click "),r("strong",null,"Repaired"),o(". Click "),r("strong",null,"Save changes"),o(".")])],-1)),a(t,{src:"/images1/maintenance/req_process_repaired.png",alt:"Edit page of Hydraulic press oil leak with Repaired highlighted in the stage bar"}),e[2]||(e[2]=s('<p>The current stage is blue. The other stages are white outlines. Each change is logged in <strong>Chatter</strong>, for example &quot;Stage :: New Request -&gt; In Progress&quot;.</p><h3 id="repaired-and-scrap" tabindex="-1">Repaired and Scrap <a class="header-anchor" href="#repaired-and-scrap" aria-label="Permalink to &quot;Repaired and Scrap&quot;">​</a></h3><p>Both stages carry the <strong>Done</strong> flag. This flag closes the request.</p><ul><li><strong>Repaired:</strong> the equipment works again.</li><li><strong>Scrap:</strong> the equipment cannot be fixed and is written off.</li></ul><p>A closed request leaves the <strong>To Do</strong> tab and appears in <strong>Done</strong>. On the calendar it turns green. See <a href="./request-list.html">Maintenance request list</a>.</p><h2 id="what-you-can-edit" tabindex="-1">What you can edit <a class="header-anchor" href="#what-you-can-edit" aria-label="Permalink to &quot;What you can edit&quot;">​</a></h2><p>The <strong>Request</strong> title is locked after creation. You can still change the equipment, the dates, the team, the responsible person, the priority, the notes and the instructions. Click <strong>Save changes</strong> to keep your edits or <strong>Cancel</strong> to leave.</p><h2 id="chatter-panel" tabindex="-1">Chatter panel <a class="header-anchor" href="#chatter-panel" aria-label="Permalink to &quot;Chatter panel&quot;">​</a></h2><p>Click the blue <strong>Chatter</strong> button at the top of the request. A side panel opens with a <strong>Close</strong> button.</p>',9)),a(t,{src:"/images1/maintenance/req_process_chatter.png",alt:"Chatter panel of Hydraulic press oil leak with the Send Message, Log Note and Schedule Activity buttons, and the File, Follower and Filters icons"}),e[3]||(e[3]=s('<ul><li><strong>Send Message:</strong> write a message to the followers.</li><li><strong>Log Note:</strong> write a note for your team.</li><li><strong>Schedule Activity:</strong> plan a task, such as a call to the supplier.</li><li><strong>File</strong> (paperclip icon with a count): attach a file.</li><li><strong>Follower</strong> (person icon with a count): choose who follows the request.</li><li><strong>Filters</strong> (funnel icon): narrow the list of <strong>Messages</strong>.</li></ul><p>The badge on the button counts the entries. Read more in <a href="./../../../getting-started/chatter.html">Chatter</a>.</p><h2 id="activities-on-the-list" tabindex="-1">Activities on the list <a class="header-anchor" href="#activities-on-the-list" aria-label="Permalink to &quot;Activities on the list&quot;">​</a></h2><p>Each row in the request list has a clock icon with the tooltip <strong>Schedule Activity</strong>. Click it to plan a task without opening the request. The row in the screenshot is an example of the icon. It is in <strong>In Progress</strong>.</p>',4)),a(t,{src:"/images1/maintenance/req_process_list_activity.png",alt:"Request list row for Hydraulic press oil leak in In Progress, with the clock icon for Schedule Activity"}),e[4]||(e[4]=s('<p>See <a href="./../../../getting-started/activities.html">Activities</a>.</p><h2 id="delete-and-restore" tabindex="-1">Delete and restore <a class="header-anchor" href="#delete-and-restore" aria-label="Permalink to &quot;Delete and restore&quot;">​</a></h2><p>Click the red <strong>Delete</strong> button on the request page, or use the row menu in the list. Aureus does not erase the request. It moves to the <strong>Cancelled</strong> view.</p><p>To bring it back, open the <strong>Cancelled</strong> view, tick the request and click <strong>Restore selected</strong>. <strong>Force delete selected</strong> removes it for good.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Force delete cannot be undone.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-request.html">Create a maintenance request</a></li><li><a href="./preventive-maintenance.html">Preventive maintenance</a></li><li><a href="./request-list.html">Maintenance request list</a></li><li><a href="./../setup/stages.html">Stages</a></li></ul>',7))])}const b=n(c,[["render",g]]);export{f as __pageData,b as default};
